import React, { useState } from 'react';
import Navbar from './components/Navbar';
import Home from './components/Home';
import Timetable from './components/Timetable';
import Teachers from './components/Teachers';
import About from './components/About';
import LmsDashboard from './components/LmsDashboard';
import Footer from './components/Footer';
import Login from './components/Login';

export default function App() {
  const [currentPage, setCurrentPage] = useState('Home');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [studentName, setStudentName] = useState('');

  // 🌐 Backend server ekat (Port 8081) login data yawana function eka
  const handleLoginSubmit = async (username, password) => {
    // Page hang wena eka nawaththanna lagatama error handle karamu
    try {
      const response = await fetch('http://localhost:8081/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, password })
      });
      
      if (!response.ok) {
        throw new Error('Server error occurred');
      }

      const data = await response.json();
      
      if (data.status === 'Success') {
        setStudentName(username);
        setIsLoggedIn(true);
        setShowLoginModal(false);
        setCurrentPage('Dashboard'); // Direct dashboard ekat yanawa
      } else {
        alert('Invalid Username or Password!');
      }
    } catch (error) {
      console.error(error);
      alert('Error: Backend Server (Port 8081) ekat connect wenna baha!');
    }
  };

  // 🚪 Logout wela apahu website eke home page ekat yana function eka
  const handleLogout = () => {
    setIsLoggedIn(false);
    setStudentName('');
    setCurrentPage('Home'); // Home page ekat yanawa
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', minHeight: '100vh', fontFamily: 'sans-serif' }}>
      {/* Navbar eka ehemama thiyenawa, login unama admin photo ekai welcome kiyala enawa */}
      <Navbar 
         onLoginClick={() => setShowLoginModal(true)} 
         isLoggedIn={isLoggedIn} 
         studentName={studentName} 
         setCurrentPage={setCurrentPage} 
         currentPage={currentPage}
      />

      {/* Meda kotasa - Content area */}
      <main style={{ flex: 1, display: 'flex', backgroundColor: '#f8fafc' }}>
        {currentPage === 'Home' && <Home />}
        {currentPage === 'Classes' && <Timetable setCurrentPage={setCurrentPage} />}
        {currentPage === 'Teachers' && <Teachers />}
        {currentPage === 'About' && <About />}
        
        {/* Dashboard eka load wenne Navbar saha Footer meda */}
        {currentPage === 'Dashboard' && isLoggedIn && (
          <LmsDashboard handleLogout={handleLogout} username={studentName} />
        )}
      </main>

      {/* Footer eka ehemama thiyenawa yarda yardatama */}
      <Footer />

      {/* Login Form Modal */}
      {showLoginModal && (
        <Login 
          setShowLoginModal={setShowLoginModal} 
          handleLoginSubmit={handleLoginSubmit} 
        />
      )}
    </div>
  );
}
